// Decision：batchMode=single 走 Form 2；batchMode=batch-all-enabled 直接全跑
const rows = $input.all().map(i => i.json);
const mode = $('00 Form — Start').first().json.batchMode;

if (mode === 'batch-all-enabled') {
  // 直接把 Sheet 全部 enabled=true 的列 emit 出去，跳過 Form 2
  const enabled = rows.filter(r => {
    const v = String(r.enabled ?? 'true').toLowerCase();
    return v === 'true' || v === '1' || v === 'yes' || v === '';
  });
  return enabled.map(r => ({ json: { ...r, __bypassPicker: true } }));
}

// single 模式：把所有 project_name 做成 options 傳給 Form 2
const options = rows
  .filter(r => r.project_name)
  .map(r => ({ option: `${r.project_name}  —  ${r.target_url || '(no url)'}` }));

// 同時把整份 rows 也帶著，供 Form 2 後的節點用 project_name 反查
return [{ json: { __pickerMode: true, options, allRows: rows } }];

// 03 Form 送回的 projectPick 是 'project_name  —  target_url' 字串
// 這裡拆出 project_name，從 allRows 找到那一列
const pick = $json.projectPick || '';
const projectName = pick.split('  —  ')[0].trim();
const scopesOverride = ($json.scopesOverride || '').trim();
const notifyOverride = ($json.notifyEmailOverride || '').trim();

const allRows = $('02 Branch — picker or batch').first().json.allRows || [];
const row = allRows.find(r => r.project_name === projectName);
if (!row) {
  throw new Error(`找不到 project_name=${projectName}（Sheet 可能在選的當下被改了）`);
}

const out = { ...row };
if (scopesOverride) out.scopes = scopesOverride;
if (notifyOverride) out.notify_email = notifyOverride;
return [{ json: out }];

// 05 Normalize — 把 row 統一成 { projectName, targetUrl, localPath, phpVersion, scopes[], envB64, notifyEmail, warnings[] }
const src = $json;

function parseScopes(raw) {
  if (Array.isArray(raw)) return raw;
  if (!raw) return [];
  return String(raw).split(',').map(s => s.trim()).filter(Boolean);
}

const ALL    = ['precheck','static','unit','api-test','db-test','links','ssl','trivy','lighthouse','e2e','nuclei','security','stress','monkey','summary'];
const REMOTE = ['precheck','ssl','security','nuclei','stress','lighthouse','links','monkey','summary'];
const LOCAL  = ['static','unit','trivy','db-test','summary'];

function expandPresets(list) {
  const out = new Set();
  for (const s of list) {
    if (s === 'ALL' || s === 'all') ALL.forEach(x => out.add(x));
    else if (s === 'REMOTE_ONLY' || s === 'remote-only') REMOTE.forEach(x => out.add(x));
    else if (s === 'LOCAL_ONLY' || s === 'local-only') LOCAL.forEach(x => out.add(x));
    else out.add(s);
  }
  return [...out];
}

const scopes = expandPresets(parseScopes(src.scopes));

// 組 .env 內容（base64 給 write-project-config.sh）
const envLines = [];
const addIf = (key, val) => { if (val) envLines.push(`${key}=${val}`); };
addIf('ADMIN_USERNAME', src.admin_username);
addIf('ADMIN_PASSWORD', src.admin_password);
addIf('E2E_USERNAME', src.e2e_username);
addIf('E2E_PASSWORD', src.e2e_password);
for (let i = 1; i <= 5; i++) {
  addIf(`USER${i}_USERNAME`, src[`user${i}_username`]);
  addIf(`USER${i}_PASSWORD`, src[`user${i}_password`]);
  addIf(`USER${i}_LABEL`,    src[`user${i}_label`]);
}
const envContent = envLines.join('\n') + (envLines.length ? '\n' : '');
const envB64 = Buffer.from(envContent, 'utf-8').toString('base64');

return {
  projectName: (src.project_name || '').trim(),
  targetUrl:   (src.target_url || '').trim(),
  localPath:   (src.local_path || '').trim(),
  phpVersion:  String(src.php_version || '8.1').trim(),
  scopes,
  scopesCsv:   scopes.join(','),
  envB64,
  notifyEmail: (src.notify_email || '').trim(),
  warnings:    []
};

// 07 Precheck — 必填檢查 + 非致命欄位缺失記 warning
const d = $json;
const warnings = [];

if (!d.projectName) throw new Error('❌ project_name 未提供');
if (!d.targetUrl)   throw new Error('❌ target_url 未提供');

const scopes = new Set(d.scopes || []);

if (!d.localPath) {
  warnings.push('⚠ local_path 未設 → 將跳過 static/unit/trivy/db-test');
  ['static','unit','trivy','db-test'].forEach(s => scopes.delete(s));
}
if (!d.targetUrl.startsWith('https://') && scopes.has('ssl')) {
  warnings.push('⚠ target_url 非 https → 跳過 SSL 掃描');
  scopes.delete('ssl');
}

const envContent = d.envB64 ? Buffer.from(d.envB64, 'base64').toString('utf-8') : '';
if (!/ADMIN_USERNAME=\S/.test(envContent) && (scopes.has('api-test') || scopes.has('auth-test'))) {
  warnings.push('⚠ 未提供 admin 帳密 → API/Auth 測試會 skip');
}
if (!/E2E_USERNAME=\S/.test(envContent) && scopes.has('e2e')) {
  warnings.push('⚠ 未提供 E2E 帳密 → e2e 只跑公開頁面');
}

const finalScopes = [...scopes];
return {
  ...d,
  scopes: finalScopes,
  scopesCsv: finalScopes.join(','),
  warnings: [...(d.warnings || []), ...warnings]
};

// 09 Extract registry path + pass-through item（合併舊 04.5 + 05.5）
const lines = ($json.stdout || '').trim().split('\n').filter(Boolean);
const registryPath = lines[lines.length - 1] || '';
if (!registryPath) throw new Error('write-project-config.sh 未回傳 registry path');
const upstream = $('07 Precheck & Warning').itemMatching($itemIndex).json;
return { ...upstream, registryPath };

// 13 Parse Results — 解析 12 的 JSON stdout
const upstream = $('09 Extract Registry Path').itemMatching($itemIndex).json;
let parsed = {};
try {
  parsed = JSON.parse($json.stdout);
} catch (e) {
  return {
    projectName: upstream.projectName,
    notifyEmail: upstream.notifyEmail,
    parseError: e.message,
    rawStdout: ($json.stdout || '').slice(0, 500),
    warnings: upstream.warnings || []
  };
}
const mergedWarnings = [...new Set([...(parsed.warnings || []), ...(upstream.warnings || [])])];
const overallScore = parsed.lighthouse?.avg?.performance ?? null;
return {
  ...parsed,
  projectName: upstream.projectName,
  notifyEmail: upstream.notifyEmail,
  overallScore,
  warnings: mergedWarnings
};

// 14 Aggregate Batch Summary — SplitInBatches done 後彙整所有 item
const items = $input.all().map(i => i.json);
const rows = items.map(r => ({
  projectName: r.projectName || '(unknown)',
  overallScore: r.overallScore ?? 'N/A',
  warningsCount: (r.warnings || []).length,
  parseError: r.parseError || '',
  reportPath: r.reports_dir ? `${r.reports_dir}/report.md` : ''
}));

const md = [
  '# 批次測試總結',
  '',
  `執行時間：${new Date().toLocaleString('zh-TW', { timeZone: 'Asia/Taipei' })}`,
  `共 ${rows.length} 個專案`,
  '',
  '| 專案 | overallScore | warnings | 報告 |',
  '|---|---|---|---|',
  ...rows.map(r => `| ${r.projectName} | ${r.overallScore} | ${r.warningsCount} | ${r.reportPath} |`)
].join('\n');

return { batchSummary: md, rows, total: rows.length };
